[tool: web_search] {
  "results": [
    {
      "title": "Flu Vaccination Recommendations for Adults 65 Years and Older",
      "url": "https://www.cdc.gov/flu/vaccines-work/older-adults.html",
      "snippet": "CDC says adults 65 years and older should get an annual flu shot, and the agency prefers higher-dose or adjuvanted flu vaccines for this age group when available. For the 2024-2025 season, options include Fluzone High-Dose, Flublok, and Fluad, which CDC lists as acceptable choices for older adults.",
      "domain": "cdc.gov",
      "rank": 1
    },
    {
      "title": "Who Should and Who Should NOT Get a Flu Vaccine",
      "url": "https://www.cdc.gov/flu/prevent/whoshouldvax.htm",
      "snippet": "CDC recommends that everyone 6 months and older get a flu vaccine each year, with extra emphasis on adults 65+ because they are at higher risk of severe illness and hospitalization. The page notes that flu vaccination is especially important as flu viruses can circulate from fall through spring, often peaking between December and February.",
      "domain": "cdc.gov",
      "rank": 2
    },
    {
      "title": "Seasonal Flu Vaccine Dosage and Administration for Older Adults",
      "url": "https://www.cdc.gov/flu/hcp/vax-summary/flu-vaccine-dosage-admin.htm",
      "snippet": "CDC guidance for 2024-2025 lists three vaccine types preferred for people 65 years and older: high-dose inactivated, adjuvanted inactivated, and recombinant flu vaccines. The agency also says older adults may receive any age-appropriate licensed flu vaccine if a preferred product is not available.",
      "domain": "cdc.gov",
      "rank": 3
    },
    {
      "title": "CDC Recommends Annual Flu Shots for Adults 65 and Older as 2024-25 Season Begins",
      "url": "https://www.reuters.com/world/us/cdc-recommends-annual-flu-shots-adults-65-older-2024-10-03/",
      "snippet": "The CDC says adults 65 and older are at increased risk of serious flu complications and should get vaccinated every year, ideally by the end of October. For the 2024-2025 season, federal health officials again highlighted higher-dose and adjuvanted flu vaccines for seniors.",
      "domain": "reuters.com",
      "rank": 4
    },
    {
      "title": "Flu Shots for Older Adults: Why CDC Prefers High-Dose Vaccines After Age 65",
      "url": "https://www.aarp.org/health/conditions-treatments/info-2024/flu-shot-older-adults.html",
      "snippet": "AARP notes that CDC recommends annual flu vaccination for adults age 65 and older and says high-dose or adjuvanted vaccines may provide a stronger immune response in seniors. The article cites CDC guidance that the preferred options include Fluzone High-Dose, Fluad, and Flublok for the 2024-2025 flu season.",
      "domain": "aarp.org",
      "rank": 5
    }
  ],
  "query": "current CDC flu vaccine guidance adults 65 and older 2024",
  "count": 5
}

