steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "Influenza vaccines for older adults",
      "url": "https://www.who.int/news-room/questions-and-answers/item/influenza-vaccines-for-older-adults",
      "snippet": "WHO notes that adults aged 65 years and older are at increased risk of severe influenza and recommends annual vaccination as the main prevention measure. For the 2024\u20132025 season, WHO continues to advise countries to prioritize older adults, pregnant women, young children, and people with chronic conditions for vaccination.",
      "domain": "who.int",
      "rank": 1
    },
    {
      "title": "WHO recommendations on influenza vaccine composition for the 2024\u20132025 season",
      "url": "https://www.who.int/teams/global-influenza-programme/vaccine-composition/2024-2025-season",
      "snippet": "The World Health Organization announced its recommendations for the 2024\u20132025 northern hemisphere influenza vaccine composition after consultations held in February 2024. The composition includes A(H1N1)pdm09, A(H3N2), and B/Victoria lineage strains, and WHO states that national programs should use locally approved age-appropriate formulations for older adults.",
      "domain": "who.int",
      "rank": 2
    },
    {
      "title": "Influenza vaccination coverage and priorities for adults 65 years and older",
      "url": "https://www.who.int/europe/news/item/2024-10-01-influenza-vaccination-older-adults",
      "snippet": "WHO Europe says adults 65+ are among the highest-risk groups for influenza-related hospitalization and death, especially during winter peaks. The agency recommends annual vaccination before influenza circulation increases and emphasizes use of high-dose or adjuvanted vaccines where available for older adults.",
      "domain": "who.int",
      "rank": 3
    },
    {
      "title": "Influenza and the elderly",
      "url": "https://www.cdc.gov/flu/highrisk/65over.htm",
      "snippet": "CDC reports that adults 65 years and older are at higher risk of serious flu complications than younger healthy adults, and most flu-related deaths occur in this age group. CDC recommends annual flu vaccination for everyone 6 months and older, with preferential use of higher-dose, adjuvanted, or recombinant vaccines for adults 65+ when available.",
      "domain": "cdc.gov",
      "rank": 4
    },
    {
      "title": "WHO global influenza programme: vaccine recommendations and use in older adults",
      "url": "https://www.who.int/teams/global-influenza-programme/influenza-vaccines",
      "snippet": "WHO\u2019s Global Influenza Programme provides guidance for seasonal influenza vaccination, including evidence reviews on vaccine effectiveness in adults 65 years and older. WHO highlights that vaccine choice may vary by country and supply, but annual vaccination remains the primary recommendation for preventing severe disease in older adults.",
      "domain": "who.int",
      "rank": 5
    }
  ],
  "query": "current WHO recommendations influenza vaccine older adults adults 65 years WHO 2024",
  "count": 5
}

