steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "High-dose and adjuvanted influenza vaccine effectiveness among adults aged 65 years and older, 2024 | PubMed",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38912345/",
      "snippet": "Published in 2024, this peer-reviewed study evaluated real-world influenza vaccine effectiveness in adults aged 65 years and older across multiple U.S. health systems. The analysis reported higher effectiveness for high-dose and adjuvanted formulations versus standard-dose vaccines during the 2023\u20132024 influenza season, with adjusted effectiveness estimates reported in the 20%\u201340% range depending on outcome.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 1
    },
    {
      "title": "Effectiveness of high-dose versus adjuvanted influenza vaccines in older adults: a multicenter observational study",
      "url": "https://www.sciencedirect.com/science/article/pii/S0264410X24001234",
      "snippet": "In this multicenter cohort of 156,482 adults aged \u226565 years, investigators compared high-dose quadrivalent and adjuvanted influenza vaccines against standard-dose vaccine during the 2023\u20132024 season. The study found a statistically significant reduction in influenza-related outpatient visits and hospitalizations, with the strongest protection observed in adults 75 years and older.",
      "domain": "sciencedirect.com",
      "rank": 2
    },
    {
      "title": "2024 influenza vaccine effectiveness in seniors: high-dose and adjuvanted vaccines show improved protection",
      "url": "https://www.nejm.org/doi/full/10.1056/NEJMoa2405678",
      "snippet": "A 2024 peer-reviewed analysis reported that older adults receiving high-dose or adjuvanted influenza vaccines had fewer medically attended influenza cases than those given standard-dose products. The paper included 18 U.S. states and estimated vaccine effectiveness of 28.6% for high-dose vaccine and 24.1% for adjuvanted vaccine against laboratory-confirmed influenza.",
      "domain": "nejm.org",
      "rank": 3
    },
    {
      "title": "Influenza vaccination in older adults: comparative effectiveness of enhanced vaccines in the 2023\u20132024 season",
      "url": "https://www.lancet.com/journals/laninf/article/PIIS1473-3099(24)00123-4/fulltext",
      "snippet": "Researchers from the Influenza Vaccine Evaluation Network followed 92,104 adults aged 65+ from October 2023 through March 2024. The Lancet Infectious Diseases article reported that both high-dose and MF59-adjuvanted vaccines reduced influenza-associated hospitalizations compared with standard-dose vaccination, with effect estimates varying by virus subtype.",
      "domain": "thelancet.com",
      "rank": 4
    },
    {
      "title": "CDC influenza vaccine effectiveness among adults 65 years and older, 2024 season",
      "url": "https://www.cdc.gov/flu/vaccines-work/2023-2024.htm",
      "snippet": "CDC\u2019s 2023\u20132024 flu vaccine effectiveness page summarizes interim results for adults 65 years and older, including enhanced vaccines such as high-dose and adjuvanted products. The report notes that effectiveness estimates differed by season and outcome, with laboratory-confirmed influenza and outpatient illness used as primary endpoints.",
      "domain": "cdc.gov",
      "rank": 5
    }
  ],
  "query": "peer reviewed study influenza vaccine effectiveness older adults 65 years high-dose adjuvanted 2024 PubMed",
  "count": 5
}

