[tool: web_search] {
  "results": [
    {
      "title": "Probability of at Least One Six in Four Rolls of a Fair Die",
      "url": "https://www.mathsisfun.com/data/probability-events-independent.html",
      "snippet": "For a fair six-sided die, the probability of getting at least one 6 in 4 rolls is 1 - (5/6)^4 = 671/1296, or about 51.77%. The complement approach counts the 5 outcomes that are not 6 on each roll, then subtracts from 1.",
      "domain": "mathsisfun.com",
      "rank": 1
    },
    {
      "title": "At Least One Six Calculator for Dice Rolls",
      "url": "https://www.omnicalculator.com/statistics/dice-probability",
      "snippet": "With 4 independent rolls of a fair die, the chance of seeing at least one six is 51.77%, since 1 - 625/1296 = 671/1296. The exact fraction comes from all 4 rolls avoiding 6, which has probability (5/6)^4.",
      "domain": "omnicalculator.com",
      "rank": 2
    },
    {
      "title": "Complement Rule in Probability: Examples with Dice",
      "url": "https://www.khanacademy.org/math/statistics-probability/probability-library",
      "snippet": "Using the complement rule, P(at least one 6 in 4 rolls) = 1 - P(no 6 in 4 rolls). For a fair die, that is 1 - (5/6)^4 = 671/1296, which is approximately 0.5177.",
      "domain": "khanacademy.org",
      "rank": 3
    },
    {
      "title": "Probability of Rolling a Six in Repeated Dice Throws",
      "url": "https://www.cuemath.com/data/probability-of-rolling-a-six/",
      "snippet": "If a die is rolled 4 times, the exact probability of getting at least one 6 is 671/1296. In decimal form, the result is 0.5177469136, often rounded to 51.8%.",
      "domain": "cuemath.com",
      "rank": 4
    },
    {
      "title": "Solved: At Least One 6 in 4 Rolls of a Fair Die",
      "url": "https://math.stackexchange.com/questions/",
      "snippet": "A standard solution uses the complement: there are 5 non-six outcomes on each roll, so the probability of no six in four rolls is (5/6)^4 = 625/1296. Therefore the probability of at least one six is 671/1296.",
      "domain": "math.stackexchange.com",
      "rank": 5
    }
  ],
  "query": "671/1296 exact probability at least one 6 in 4 rolls fair die",
  "count": 5
}

