      "rank": 4
    },
    {
      "title": "Influenza vaccine effectiveness and hospitalizations in older adults: 2024 PubMed review",
      "url": "https://pubmed.ncbi.nlm.nih.gov/?term=influenza+vaccine+effectiveness+adults+65+years+older+2023+2024+hospitalization",
