[tool: web_search] {
  "results": [
    {
      "title": "numpy.std \u2014 NumPy v2.0 Manual",
      "url": "https://numpy.org/doc/stable/reference/generated/numpy.std.html",
      "snippet": "Compute the standard deviation along the specified axis, with `ddof=0` by default, which gives the population standard deviation. NumPy documents the formula as `sqrt(mean(abs(x - x.mean())**2))` and notes that setting `ddof=1` changes the divisor to `N-1` for the sample standard deviation.",
      "domain": "numpy.org",
      "rank": 1
    },
    {
      "title": "Coefficient of Variation in Python: Using NumPy and SciPy",
      "url": "https://realpython.com/python-coefficient-of-variation/",
      "snippet": "Shows how to calculate coefficient of variation as `CV = std / mean`, often multiplied by 100 to express a percentage. The guide uses `numpy.std(..., ddof=0)` for population data and explains that a dataset with mean 50 and standard deviation 5 has a CV of 0.10, or 10%.",
      "domain": "realpython.com",
      "rank": 2
    },
    {
      "title": "Standard Deviation \u2014 Statistics and Data Analysis",
      "url": "https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.tstd.html",
      "snippet": "SciPy\u2019s documentation distinguishes between population and sample formulas, using `ddof=0` for population calculations and `ddof=1` for sample estimates. The related NumPy and SciPy functions are commonly used with arrays of any shape, including 1-D vectors and multi-dimensional matrices.",
      "domain": "docs.scipy.org",
      "rank": 3
    },
    {
      "title": "How to Calculate Coefficient of Variation in Python",
      "url": "https://www.geeksforgeeks.org/how-to-calculate-coefficient-of-variation-in-python/",
      "snippet": "The coefficient of variation is defined as the ratio of the standard deviation to the mean, and the article includes a simple example where `std = 2.5` and `mean = 25`, producing a CV of `0.1`. It also shows a NumPy implementation using `np.std(arr)` and `np.mean(arr)` for quick comparison across datasets.",
      "domain": "geeksforgeeks.org",
      "rank": 4
    },
    {
      "title": "Population Standard Deviation in NumPy with ddof=0",
      "url": "https://www.statology.org/population-standard-deviation-numpy/",
      "snippet": "Explains that NumPy\u2019s default `np.std()` uses `ddof=0`, which matches the population standard deviation formula `sqrt(sum((x - \u03bc)^2)/N)`. The page also shows how to convert the result to a coefficient of variation by dividing the standard deviation by the mean, such as `12 / 60 = 0.20`.",
      "domain": "statology.org",
      "rank": 5
    }
  ],
  "query": "Python numpy population standard deviation coefficient of variation formula",
  "count": 5
}

