  "results": [
    {
      "title": "Effectiveness of High-Dose and Adjuvanted Influenza Vaccines in Adults Aged 65 Years and Older: 2023\u20132024 Season",
      "url": "https://www.cdc.gov/flu/vaccines-work/older-adults-2024.htm",
      "snippet": "CDC data from the 2023\u20132024 season found that high-dose and adjuvanted flu vaccines were associated with better protection than standard-dose vaccines in adults 65 and older. In one multi-site analysis, vaccine effectiveness against medically attended influenza was about 26% overall in this age group, with higher estimates for enhanced vaccines in some outcomes.",
      "domain": "cdc.gov",
      "rank": 1
    },
    {
      "title": "Peer-Reviewed Study: Influenza Vaccine Effectiveness Among Adults 65+ During the 2022\u20132023 Season",
      "url": "https://www.sciencedirect.com/science/article/pii/S0264410X24001234",
      "snippet": "A 2024 peer-reviewed analysis in Vaccine reported that influenza vaccination reduced outpatient visits and hospitalizations among adults aged 65 years and older, with effectiveness estimates varying by virus subtype. The study included more than 18,000 test-negative encounters across 12 U.S. health systems and found stronger protection against A(H1N1)pdm09 than against A(H3N2).",
      "domain": "sciencedirect.com",
      "rank": 2
    },
    {
      "title": "High-Dose Quadrivalent Influenza Vaccine in Older Adults: Updated Effectiveness Findings",
      "url": "https://www.nejm.org/doi/full/10.1056/NEJMoa2401123",
      "snippet": "An updated paper in the New England Journal of Medicine reported that high-dose quadrivalent influenza vaccine was associated with fewer laboratory-confirmed flu cases in adults 65 and older compared with standard-dose vaccine. The authors noted a relative vaccine effectiveness of roughly 15% to 20% across recent seasons, with the largest benefit observed in peak transmission weeks.",
      "domain": "nejm.org",
      "rank": 3
    },
    {
      "title": "Influenza Vaccine Effectiveness in Older Adults: Meta-analysis of Randomized and Observational Studies",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38901234/",
      "snippet": "This PubMed-indexed review pooled results from 14 studies published between 2019 and 2024 and concluded that enhanced influenza vaccines provided modest but measurable benefit in adults 65+. The meta-analysis reported reduced influenza-related hospitalization risk, with pooled effect sizes ranging from 0.74 to 0.88 depending on vaccine type and outcome.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 4
    },
    {
      "title": "Flu Vaccines for Seniors: What Recent Studies Show About Effectiveness",
      "url": "https://www.healthline.com/health/flu-vaccine-effectiveness-seniors",
      "snippet": "Recent studies cited in this article found that flu vaccines in adults 65 and older can lower the risk of hospitalization by about 30% to 40% in years when the vaccine matches circulating strains well. Researchers from the University of Pittsburgh and Kaiser Permanente were among those reporting that high-dose and adjuvanted vaccines tend to perform better than standard-dose shots in older adults.",
      "domain": "healthline.com",
      "rank": 5
    }
  ],
  "query": "recent peer-reviewed effectiveness data on flu vaccines for adults 65+",
  "count": 5
}

