[tool: web_search] {
  "results": [
    {
      "title": "ACIP Recommendations Summary | Influenza (Flu) Vaccination for Persons 65 Years and Older",
      "url": "https://www.cdc.gov/flu/highrisk/65over.htm",
      "snippet": "CDC recommends that adults 65 years and older get a flu shot every season, preferably in September or October. Since the 2020-2021 season, ACIP has recommended 3 higher-dose or adjuvanted vaccine options for this age group: Fluzone High-Dose Quadrivalent, Flublok Quadrivalent, and Fluad Quadrivalent.",
      "domain": "cdc.gov",
      "rank": 1
    },
    {
      "title": "Use of Higher-Dose and Adjuvanted Influenza Vaccines in Adults 65 Years and Older: ACIP Recommendations, United States, 2024\u201325",
      "url": "https://www.cdc.gov/mmwr/volumes/73/rr/rr7302a1.htm",
      "snippet": "In 2024, CDC\u2019s Advisory Committee on Immunization Practices reaffirmed that adults aged 65 years and older should preferentially receive one of three enhanced flu vaccines. The report cites evidence from randomized trials showing a stronger immune response in this age group compared with standard-dose influenza vaccine.",
      "domain": "cdc.gov",
      "rank": 2
    },
    {
      "title": "Influenza Vaccination: Adults 65 Years and Older \u2014 Advisory Committee on Immunization Practices Archive",
      "url": "https://www.cdc.gov/vaccines/acip/recs/grade/influenza-older-adults-archive.html",
      "snippet": "This archive compiles ACIP voting records, evidence reviews, and meeting slides related to flu vaccination guidance for adults 65+. The archive includes materials from recent seasons such as 2022\u201323, 2023\u201324, and 2024\u201325, with links to MMWR recommendations and vaccine efficacy tables.",
      "domain": "cdc.gov",
      "rank": 3
    },
    {
      "title": "Flu and People 65 Years and Older",
      "url": "https://www.nia.nih.gov/health/flu-and-older-adults",
      "snippet": "NIH\u2019s National Institute on Aging notes that people 65 and older are at higher risk for serious flu complications, including hospitalization. It recommends annual flu vaccination and says older adults may benefit from high-dose or adjuvanted vaccines, which are designed to produce a stronger immune response.",
      "domain": "nih.gov",
      "rank": 4
    },
    {
      "title": "ACIP Flu Vaccine Recommendations by Age Group",
      "url": "https://www.immunize.org/askexperts/experts_flu_age.asp",
      "snippet": "Immunize.org summarizes ACIP guidance for the 2024\u201325 season, including the recommendation that adults 65 years and older receive a higher-dose, adjuvanted, or recombinant influenza vaccine when available. The page also links to archived ACIP statements dating back to earlier seasons and reviews the 3.8 million flu-related hospitalizations estimated by CDC for 2019\u201320.",
      "domain": "immunize.org",
      "rank": 5
    }
  ],
  "query": "advisory archive on flu vaccines for adults 65+",
  "count": 5
}

