    {
      "title": "Attention Is All You Need",
      "url": "https://arxiv.org/abs/1706.03762",
      "snippet": "In this 2017 paper, Ashish Vaswani, Noam Shazeer, Niki Parmar, Jakob Uszkoreit, Llion Jones, Aidan N. Gomez, \u0141ukasz Kaiser, and Illia Polosukhin introduce the Transformer architecture for sequence transduction. The paper reports state-of-the-art results on WMT 2014 English-to-German and English-to-French translation, with 8 attention heads in the base model.",
      "domain": "arxiv.org",
      "rank": 1
    },
    {
      "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding",
      "url": "https://arxiv.org/abs/1810.04805",
      "snippet": "Jacob Devlin, Ming-Wei Chang, Kenton Lee, and Kristina Toutanova present BERT, a bidirectional Transformer pre-trained on masked language modeling and next sentence prediction. The paper reports 80.5 F1 on SQuAD v1.1 and 93.2% accuracy on the GLUE benchmark, helping make the model one of the most cited NLP papers from 2018.",
      "domain": "arxiv.org",
      "rank": 2
    },
    {
      "title": "Transformer-XL: Attentive Language Models Beyond a Fixed-Length Context",
      "url": "https://arxiv.org/abs/1901.02860",
      "snippet": "Zihang Dai, Zhilin Yang, Yiming Yang, Jaime Carbonell, Quoc V. Le, and Ruslan Salakhutdinov propose Transformer-XL, which introduces segment-level recurrence and relative positional encoding. On WikiText-103, the paper reports a test perplexity of 18.3, improving long-context language modeling over earlier Transformer baselines.",
      "domain": "arxiv.org",
      "rank": 3
    },
    {
      "title": "The Landscape of Transformer Models in NLP: A Survey of Attention Mechanisms and Pretrained Language Models",
      "url": "https://arxiv.org/abs/2002.00000",
      "snippet": "A survey-style arXiv result from 2020 summarizes the rapid adoption of self-attention in NLP after the 2017 Transformer paper and the 2018 BERT release. It highlights how multi-head attention, positional encodings, and masked pretraining became standard in models such as RoBERTa, XLNet, and Transformer-XL.",
      "domain": "arxiv.org",
      "rank": 4
    },
    {
      "title": "A Survey of the Transformer Architecture for Sequence Modeling",
      "url": "https://arxiv.org/abs/2007.00000",
      "snippet": "This 2020 arXiv survey reviews highly cited Transformer papers published between 2017 and 2020, including 'Attention Is All You Need,' BERT, and Transformer-XL. The abstract notes that the Transformer family replaced recurrence in many NLP tasks and that attention-based models now dominate machine translation and language understanding benchmarks.",
      "domain": "arxiv.org",
      "rank": 5
    }
  ],
  "query": "site:arxiv.org transformer attention mechanisms 2017 2020 highly cited papers 'Attention Is All You Need' 'BERT' 'Transformer-XL'",
  "count": 5
}

