steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "Influenza Vaccine Effectiveness in Adults Aged 65 Years and Older: A Systematic Review and Meta-analysis",
      "url": "https://pubmed.ncbi.nlm.nih.gov/37948211/",
      "snippet": "Published in 2024, this systematic review and meta-analysis evaluated seasonal influenza vaccine effectiveness in adults aged 65 years and older across multiple influenza seasons. The review synthesized estimates from 18 observational studies and reported pooled effectiveness ranging from 27% to 41% depending on vaccine match and outcome.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 1
    },
    {
      "title": "Systematic Review of Influenza Vaccine Effectiveness in Older Adults During the 2023-2024 Season",
      "url": "https://www.sciencedirect.com/science/article/pii/S0264410X24001234",
      "snippet": "A 2024 peer-reviewed review in Vaccine examined influenza vaccine effectiveness among adults 65+ using test-negative design studies and registry data from North America and Europe. The authors reported substantially higher effectiveness against hospitalization for adjuvanted and high-dose vaccines, with point estimates near 20% to 50% in several studies.",
      "domain": "sciencedirect.com",
      "rank": 2
    },
    {
      "title": "Seasonal Influenza Vaccines in Adults Aged 65 Years and Older: Evidence Review and Comparative Effectiveness",
      "url": "https://www.thelancet.com/journals/laninf/article/PIIS1473-3099(24)00187-6/fulltext",
      "snippet": "This peer-reviewed 2024 evidence review in The Lancet Infectious Diseases summarized randomized and observational data for older adults and found that high-dose and adjuvanted influenza vaccines generally outperformed standard-dose vaccines. In the included studies, vaccine effectiveness against laboratory-confirmed influenza commonly ranged from 15% to 45%, with stronger protection against severe outcomes.",
      "domain": "thelancet.com",
      "rank": 3
    },
    {
      "title": "CDC: Flu & People 65 Years and Older",
      "url": "https://www.cdc.gov/flu/highrisk/65over.htm",
      "snippet": "CDC notes that adults 65 years and older are at higher risk of serious flu complications and recommends annual influenza vaccination with a preferred higher-dose or adjuvanted vaccine when available. The page cites surveillance showing that flu vaccination reduced the risk of flu-related doctor visits and hospitalizations, with protection varying by season and vaccine type.",
      "domain": "cdc.gov",
      "rank": 4
    },
    {
      "title": "Influenza Vaccination in Older Adults: Updated Systematic Review and Meta-analysis, 2023-2024",
      "url": "https://pubmed.ncbi.nlm.nih.gov/?term=influenza+vaccine+effectiveness+older+adults+systematic+review+2024",
      "snippet": "An updated PubMed-indexed review from 2024 pooled data from studies published between 2010 and 2023 and focused on adults aged 65+ receiving seasonal influenza vaccination. The abstract reports that included studies used test-negative and cohort designs, with the strongest effects observed for prevention of influenza-associated hospitalization.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 5
    }
  ],
  "query": "peer reviewed influenza vaccine effectiveness older adults 65 years systematic review 2023 2024",
  "count": 5
}

