  "results": [
    {
      "title": "Attention Is All You Need",
      "url": "https://arxiv.org/abs/1706.03762",
      "snippet": "Ashish Vaswani, Noam Shazeer, Niki Parmar, Jakob Uszkoreit, Llion Jones, Aidan N. Gomez, \u0141ukasz Kaiser and Illia Polosukhin introduced the Transformer in 2017. The paper has been cited tens of thousands of times on Semantic Scholar and describes multi-head attention with 8 heads and a model dimension of 512.",
      "domain": "arxiv.org",
      "rank": 1
    },
    {
      "title": "Attention Is All You Need - Semantic Scholar",
      "url": "https://www.semanticscholar.org/paper/Attention-Is-All-You-Need-Vaswani-Shazeer/",
      "snippet": "Semantic Scholar lists the 2017 Transformer paper by Vaswani et al. as one of the most influential works in NLP, with citation counts exceeding 60,000 in many indexes. The entry shows the authors, publication year, and a concise abstract highlighting self-attention and positional encoding.",
      "domain": "semanticscholar.org",
      "rank": 2
    },
    {
      "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding",
      "url": "https://arxiv.org/abs/1810.04805",
      "snippet": "Jacob Devlin, Ming-Wei Chang, Kenton Lee and Kristina Toutanova published BERT in 2018, building on the Transformer attention mechanism introduced in 2017. The paper reports state-of-the-art results on GLUE and SQuAD and is widely cited as a key follow-up to 'Attention Is All You Need'.",
      "domain": "arxiv.org",
      "rank": 3
    },
    {
      "title": "Transformer-XL: Attentive Language Models Beyond a Fixed-Length Context",
      "url": "https://arxiv.org/abs/1901.02860",
      "snippet": "Zihang Dai, Zhilin Yang, Yiming Yang, Jauregui, Quoc V. Le and Ruslan Salakhutdinov proposed Transformer-XL in 2019, extending attention to longer contexts with segment-level recurrence. The paper is cited for improving language modeling on WikiText-103 and enwiki8 with more than 1000 citations in major academic databases.",
      "domain": "arxiv.org",
      "rank": 4
    },
    {
      "title": "Longformer: The Long-Document Transformer",
      "url": "https://arxiv.org/abs/2004.05150",
      "snippet": "Iz Beltagy, Matthew E. Peters and Arman Cohan released Longformer in 2020, introducing sparse attention to handle sequences of 4,096 tokens and beyond. The paper is frequently cited in document understanding and summarization research and is indexed in Semantic Scholar with author and citation metadata.",
      "domain": "arxiv.org",
      "rank": 5
    }
  ],
  "query": "highly cited transformer attention mechanism paper 2017 2018 2019 2020 citation semantic scholar attention transformer title authors year",
  "count": 5
}

