    {
      "title": "Effectiveness of the 2023-2024 influenza vaccine in adults aged 65 years and older",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38765421/",
      "snippet": "Published in 2024, this study estimated vaccine effectiveness against medically attended influenza among adults 65 years and older during the 2023-2024 season. The investigators reported adjusted effectiveness of 31% overall, with higher protection against influenza A(H1N1)pdm09 than against influenza A(H3N2).",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 1
    },
    {
      "title": "Seasonal influenza vaccination and severe outcomes in older adults: a multicenter cohort study",
      "url": "https://www.nejm.org/doi/full/10.1056/NEJMoa2401187",
      "snippet": "In a 2024 multicenter analysis of adults 65 years of age or older, seasonal influenza vaccination was associated with a reduced risk of hospitalization for influenza-related complications. The study followed 42,318 participants across 12 U.S. health systems and found 24% effectiveness against hospital admission.",
      "domain": "nejm.org",
      "rank": 2
    },
    {
      "title": "Relative vaccine effectiveness of high-dose versus standard-dose influenza vaccine among adults 65 years and older, 2024",
      "url": "https://www.thelancet.com/journals/lancet/article/PIIS0140-6736(24)00567-8/fulltext",
      "snippet": "Researchers comparing high-dose and standard-dose influenza vaccines in 2024 reported a 15.4% relative vaccine effectiveness advantage for the high-dose formulation in adults aged 65+ years. The analysis included 9,870 influenza test-negative patients from five countries and was published online in May 2024.",
      "domain": "thelancet.com",
      "rank": 3
    },
    {
      "title": "Influenza vaccine effectiveness in U.S. adults aged 65 years and older during the 2023\u201324 season",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38810277/",
      "snippet": "A 2024 test-negative study of 65+ adults found the seasonal influenza vaccine reduced outpatient visits for lab-confirmed influenza by 29% overall. Effectiveness was greatest against influenza B at 44% and lowest against H3N2 at 18% among patients enrolled from October 2023 through March 2024.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 4
    },
    {
      "title": "High-dose and adjuvanted influenza vaccines in older adults: updated evidence from 2024",
      "url": "https://www.nejm.org/doi/full/10.1056/NEJMra2400721",
      "snippet": "An updated 2024 review summarized randomized and observational data in adults 65 years of age and older, noting that enhanced influenza vaccines consistently outperformed standard-dose formulations. Across 18 studies and more than 1.2 million vaccine doses, reported effectiveness ranged from 10% to 36% depending on circulating strains.",
      "domain": "nejm.org",
      "rank": 5
    }
  ],
  "query": "peer reviewed influenza vaccine effectiveness older adults 65 years 2024 study site:pubmed.ncbi.nlm.nih.gov OR site:nejm.org OR site:thelancet.com",
  "count": 5
}

