[tool: web_search] {
  "results": [
    {
      "title": "numpy.std \u2014 NumPy v2.1 Manual",
      "url": "https://numpy.org/doc/stable/reference/generated/numpy.std.html",
      "snippet": "`numpy.std` computes the standard deviation along the specified axis and defaults to the population formula with `ddof=0`. The docs show that `np.std([1,2,3,4])` returns `1.118033988749895`, and note that the coefficient of variation can be computed as `std / mean` when the mean is nonzero.",
      "domain": "numpy.org",
      "rank": 1
    },
    {
      "title": "Coefficient of variation - Wikipedia",
      "url": "https://en.wikipedia.org/wiki/Coefficient_of_variation",
      "snippet": "The coefficient of variation is defined as the ratio of the standard deviation to the mean, often expressed as a percentage. For a data set with mean 50 and standard deviation 5, the CV is 10%; the page also notes that the measure is commonly used to compare dispersion across datasets with different units or scales.",
      "domain": "wikipedia.org",
      "rank": 2
    },
    {
      "title": "Standard Deviation in Python with NumPy and pandas",
      "url": "https://realpython.com/python-standard-deviation/",
      "snippet": "This tutorial explains the difference between population and sample standard deviation in Python, using `ddof=0` for population and `ddof=1` for sample calculations. It includes NumPy examples such as `np.std([1, 2, 3, 4, 5])`, which returns about `1.4142` for the population standard deviation.",
      "domain": "realpython.com",
      "rank": 3
    },
    {
      "title": "Statistics: Standard Deviation and Variance",
      "url": "https://docs.scipy.org/doc/numpy/reference/generated/numpy.std.html",
      "snippet": "NumPy documents `std` as the standard deviation, with `ddof=0` producing the population standard deviation and `ddof=1` the unbiased sample estimate. The example section shows how changing `ddof` affects results for arrays like `[1, 2, 3, 4]`, where the denominator changes from `N` to `N-1`.",
      "domain": "docs.scipy.org",
      "rank": 4
    },
    {
      "title": "How to Calculate Coefficient of Variation in Python",
      "url": "https://www.geeksforgeeks.org/how-to-calculate-coefficient-of-variation-in-python/",
      "snippet": "This guide shows a Python example using NumPy to calculate coefficient of variation as `np.std(data) / np.mean(data) * 100`. In one example with data `[10, 12, 23, 23, 16, 23, 21, 16]`, the article reports a CV of about `28.0%` when using the population standard deviation.",
      "domain": "geeksforgeeks.org",
      "rank": 5
    }
  ],
  "query": "Python statistics population standard deviation coefficient of variation formula numpy example",
  "count": 5
}

